  "state": {"receipt": "Corner Cafe, 2 coffees, total 7.40"},
  "questions": {
    "merchant": {"type": "text", "instructions": "Merchant name", "max_length": 80},
    "total": {"type": "number", "instructions": "Total paid", "min": 0, "min_confidence": 0.9},
    "tip": {"type": "number", "instructions": "Tip amount", "min": 0, "nullable": true}
  }
}

from curva import Curva, Integer, Number

d = Curva().decide(
    {"invoice": "ACME Inc. / Invoice 2291 / 3 x Widget @ 4.10 / Shipping 2.00 / Total due 14.30 EUR"},
    {
        "qty": Integer("Quantity of the line item", min=0),
        "unit_price": Number("Unit price of the line item", min=0),
        "shipping": Number("Shipping cost", min=0, nullable=True),
        "total": Number("Total amount due", min=0),
    },
)
v = {k: d[k].value for k in ("qty", "unit_price", "shipping", "total")}
if None in (v["qty"], v["unit_price"], v["total"]):
    needs_review = True
else:
    expected = v["qty"] * v["unit_price"] + (v["shipping"] or 0)
    needs_review = abs(expected - v["total"]) > 0.005
